CREATE TABLE IF NOT EXISTS "Publishers" (
    "Publisher_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Publisher_name" text,
    "Publisher_city" text
);

CREATE TABLE IF NOT EXISTS "Readers" (
    "Reader_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Reader_full_name" text,
    "Reader_address" text,
    "Reader_phone" text
);

CREATE TABLE IF NOT EXISTS "Books" (
    "Book_cipher" text PRIMARY KEY,
    "First_author" text,
    "Book_name" text NOT NULL,
    "Year_of_publication" integer,
    "Book_price" integer NOT NULL CHECK ("Book_price" > 0),
    "Number_of_copies" integer NOT NULL CHECK ("Number_of_copies" >= 0),
    "Publisher_id" integer NOT NULL REFERENCES "Publishers" ("Publisher_id") ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "Loans" (
    "Reader_id" integer NOT NULL REFERENCES "Readers" ("Reader_id") ON DELETE RESTRICT,
    "Book_cipher" text NOT NULL REFERENCES "Books" ("Book_cipher") ON DELETE RESTRICT,
    "Date_of_issue" date NOT NULL CHECK ("Date_of_issue" <= CURRENT_DATE),
    "Signature" text NOT NULL,
    "Loan_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
);

CREATE TABLE IF NOT EXISTS "User" (
    "Login" text NOT NULL,
    "Password" text NOT NULL
);

-- Тестовый пользователь для получения JWT-токена: admin / admin123.
-- Пароль хранится в открытом виде только для учебного проекта — замените его.
INSERT INTO "User" ("Login", "Password")
SELECT 'admin', 'admin123'
WHERE NOT EXISTS (SELECT 1 FROM "User");
